#!/usr/bin/env node
/* build-extended-points-doc.js: generates EXTENDED-POINTS-REFERENCE.md
 * directly from ephemeris/pointRegistry.ts + its SYMBOLISM map.
 *
 * The file it writes used to claim "auto-generated from the registry" while
 * being hand-typed and stale: it said "98 points" and "81+ expanded" while
 * the registry itself has always held 97 and 80. A document that claims to
 * be generated and is not is worse than one that says nothing, because a
 * reader has no reason to doubt it. This script is what makes the claim
 * true: run it after any registry change and the counts, the category
 * groupings and the one-line symbolism per point can never drift from what
 * pointRegistry.ts actually exports, because they are read from it rather
 * than retyped.
 *
 * Same require pattern as check-point-registry.js: Node's native TypeScript
 * support strips the type-only syntax, so this needs no build step and no
 * separate transform to keep in sync with the source it reads.
 *
 * Usage: node tools/build-extended-points-doc.js
 */
'use strict';

const fs = require('fs');
const path = require('path');

const repo = path.resolve(__dirname, '..');
const REGISTRY_PATH = path.join(repo, 'app', 'ephemeris', 'pointRegistry.ts');
const OUT_PATH = path.join(repo, 'EXTENDED-POINTS-REFERENCE.md');

function die(m) { console.error('build-extended-points-doc: ' + m); process.exit(1); }

let R;
try {
  R = require(REGISTRY_PATH);
} catch (e) {
  die('pointRegistry.ts does not compile: ' + e.message);
}

const basic = R.basicPoints();
const expanded = R.expandedPoints();
const all = R.allPoints();
const SYMBOLISM = R.SYMBOLISM || {};

if (!expanded.length) die('expandedPoints() returned no points; refusing to write an empty reference');

// Declared order, not sorted: an order that moved with the data would read
// as meaning something (the same reasoning hd-transit.js's own PLNS order
// holds to). This is the category vocabulary check-point-registry.js
// enforces, minus 'angle' and 'body', which are the basic seventeen and
// never appear among the added eighty.
const CATEGORY_ORDER = ['asteroid', 'centaur', 'tno', 'node', 'comet', 'hypothetical', 'derived'];
const CATEGORY_TITLE = {
  asteroid: 'Asteroids', centaur: 'Centaurs', tno: 'TNOs & Dwarf Astral Bodies',
  node: 'Nodes & Lunar Points', comet: 'Comets (Mundane)',
  hypothetical: 'Hypotheticals (TNPs)', derived: 'Derived & Midpoints'
};

const byCategory = {};
expanded.forEach(p => { (byCategory[p.category] = byCategory[p.category] || []).push(p); });

const unlisted = Object.keys(byCategory).filter(c => CATEGORY_ORDER.indexOf(c) === -1);
if (unlisted.length) die('expandedPoints() carries a category this generator does not know: ' + unlisted.join(', '));

const lines = [];
lines.push('# Extended Points Reference');
lines.push('');
lines.push('Auto-generated by `tools/build-extended-points-doc.js` from ' +
  '`app/ephemeris/pointRegistry.ts` and its `SYMBOLISM` map. Do not hand-edit: ' +
  're-run the generator after any registry change, since this file’s only job ' +
  'is to never say something the registry does not.');
lines.push('');
lines.push('The registry holds **' + all.length + ' points** in total: the ' +
  '**' + basic.length + '** basic points every chart already carried, plus the ' +
  '**' + expanded.length + '** points below that the expanded chart adds. ' +
  '`tools/check-ephemeris-engine.js` and `tools/check-registry-integration.js` ' +
  'are what confirm each one actually computes, or honestly says it cannot; this ' +
  'file only names what each one means.');
lines.push('');

CATEGORY_ORDER.forEach(cat => {
  const rows = byCategory[cat];
  if (!rows || !rows.length) return;
  lines.push('## ' + CATEGORY_TITLE[cat] + ' (' + rows.length + ')');
  lines.push('');
  lines.push('| Point | Glyph | Symbolism |');
  lines.push('|---|---|---|');
  rows.forEach(p => {
    const sym = (SYMBOLISM[p.id] && SYMBOLISM[p.id].symbolism) || p.tooltip || '';
    const glyph = String(p.glyph || '').replace(/\|/g, '\\|');
    const name = String(p.name || p.id).replace(/\|/g, '\\|');
    const symEsc = String(sym).replace(/\|/g, '\\|');
    lines.push('| ' + name + ' | ' + glyph + ' | ' + symEsc + ' |');
  });
  lines.push('');
});

fs.writeFileSync(OUT_PATH, lines.join('\n'));

console.log('build-extended-points-doc: wrote ' + OUT_PATH);
console.log('  basic points     ' + basic.length);
console.log('  expanded points  ' + expanded.length + ', across ' + CATEGORY_ORDER.filter(c => byCategory[c] && byCategory[c].length).length + ' categories');
console.log('  total points     ' + all.length);
